74	fn set_timeout_cancel() {
75	    let clock = Rc::new(FixedClock::default());
76	    let context = &mut create_context(clock.clone());
77	    let clock1 = clock.clone();
78	    let clock2 = clock.clone();
79	
80	    run_test_actions_with(
