83	                called = false;
84	                id = setTimeout(() => { called = true; }, 100);
85	            "#}),
86	            TestAction::inspect_context_async(async |ctx| {
87	                let clock = clock1;
88	
89	                let called = ctx.global_object().get(js_str!("called"), ctx).unwrap();
90	                let ctx = &RefCell::new(ctx);
