189	/// Utility trait to "expect" a `JsResult`, but returning a `PanicError` instead of panicking.
190	#[allow(dead_code)]
191	pub(crate) trait JsExpect<V> {
192	    /// "expects" a `JsResult`, wrapping the error with a `PanicError`.
193	    fn js_expect<S: Into<Box<str>>>(self, msg: S) -> StdResult<V, PanicError>;
194	}
195	
196	impl<V> JsExpect<V> for JsResult<V> {
197	    fn js_expect<S: Into<Box<str>>>(self, msg: S) -> StdResult<V, PanicError> {
198	        self.map_err(|err| PanicError::new(msg).with_source(err))
199	    }
200	}
201	
202	impl<V> JsExpect<V> for Option<V> {
203	    fn js_expect<S: Into<Box<str>>>(self, msg: S) -> StdResult<V, PanicError> {
204	        self.ok_or_else(|| PanicError::new(msg))
205	    }
206	}
