348	fn run_test_actions(actions: impl IntoIterator<Item = TestAction>) {
349	    let mut context = Context::builder();
350	    if cfg!(miri) {
351	        // Do not use OS APIs when running with Miri to avoid escaping the
352	        // isolated sandbox.
353	
354	        use std::rc::Rc;
355	
356	        use crate::{context::time::FixedClock, module::IdleModuleLoader};
357	
358	        context = context
359	            .clock(Rc::new(FixedClock::from_millis(65535)))
360	            .module_loader(Rc::new(IdleModuleLoader));
361	    }
362	    run_test_actions_with(actions, &mut context.build().unwrap());
363	}
